describe('Account Lockout After Failed Login Attempts', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should lock an account after 5 failed login attempts', () => {
    // Attempt 1
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');
    cy.get('[data-testid="attempts-counter"]').should('contain', '1');

    // Attempt 2
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');
    cy.get('[data-testid="attempts-counter"]').should('contain', '2');

    // Attempt 3
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');
    cy.get('[data-testid="attempts-counter"]').should('contain', '3');

    // Attempt 4
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');
    cy.get('[data-testid="attempts-counter"]').should('contain', '4');

    // Attempt 5 - Account should now be locked
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Account locked');
    cy.get('[data-testid="account-status"]').should('contain', 'Locked');
    cy.get('[data-testid="reset-password-link"]').should('be.visible');
  });

  it('should allow login with correct credentials before account is locked', () => {
    // Attempt 1 (Wrong password)
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');
    cy.get('[data-testid="attempts-counter"]').should('contain', '1');

    // Attempt 2 (Wrong password)
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');
    cy.get('[data-testid="attempts-counter"]').should('contain', '2');

    // Attempt 3 (Correct password - should succeed and reset counter)
    cy.get('[data-testid="password-input"]').clear().type('correctpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible').should('contain', 'Welcome');
    cy.get('[data-testid="attempts-counter"]').should('not.exist');
  });
});
